const learning = db.getSiblingDB("devatlas_learning");
learning.lesson_day2.updateOne({ _id: "tea" }, { $set: { stock: 5 } }, { upsert: true });
learning.lesson_day2.updateOne({ _id: "tea", stock: { $gte: 2 } }, { $inc: { stock: -2 } });
print(learning.lesson_day2.findOne({ _id: "tea" }).stock);
const refused = learning.lesson_day2.updateOne({ _id: "tea", stock: { $gte: 9 } }, { $inc: { stock: -9 } });
print(refused.matchedCount);

